const products=[
{id:'honey',name:'Golden Honey',category:'pantry',tag:'THE PANTRY ESSENTIAL',subtitle:'A little sweetness for slow mornings.',image:'assets/hive-collection.png',description:'A honey-inspired pantry essential for your morning toast, favorite recipes and afternoon tea. Final variety, origin and jar size will be announced before launch.'},
{id:'propolis',name:'Propolis Drops',category:'care',tag:'FROM THE HIVE',subtitle:'Discover the remarkable world of propolis.',image:'assets/hive-collection.png',description:'Meet propolis, a bee-derived ingredient at the heart of the Propinatural concept. Formulation, ingredients and usage information will be provided before this product is offered for sale.'},
{id:'balm',name:'Beeswax Balm',category:'care',tag:'A DAILY RITUAL',subtitle:'A pocket-sized moment of care.',image:'assets/hive-collection.png',description:'A beeswax-inspired balm concept for your daily care routine. The final ingredient list, fragrance options, size and directions will be confirmed before launch.'},
{id:'candle',name:'Beeswax Candle',category:'home',tag:'SLOWER MOMENTS',subtitle:'Bring a little warmth to your space.',image:'assets/hive-collection.png',description:'A rolled beeswax candle concept for quiet evenings and thoughtful gifting. Dimensions, burn time and complete care instructions will be confirmed before launch.'}
];
let bag={};try{const saved=JSON.parse(localStorage.getItem('propinatural-bag')||'{}');for(const p of products){if(Number.isInteger(saved[p.id])&&saved[p.id]>0)bag[p.id]=Math.min(saved[p.id],99)}}catch{}
const $=s=>document.querySelector(s);let toastTimer;
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function saveBag(){try{localStorage.setItem('propinatural-bag',JSON.stringify(bag))}catch{}$('#bag-count').textContent=Object.values(bag).reduce((a,b)=>a+b,0);renderBag()}
function addProduct(id){if(!products.some(p=>p.id===id))throw new Error('Unknown product');bag[id]=Math.min((bag[id]||0)+1,99);saveBag();notify('Added to your preview bag');return{id,quantity:bag[id]}}
function renderProducts(filter='all'){$('#products').innerHTML=products.filter(p=>filter==='all'||p.category===filter).map(p=>`<article class="product-card"><div class="product-photo"><img src="${p.image}" alt="${p.name} concept product photograph" loading="lazy"><span class="product-tag">${p.tag}</span></div><h3>${p.name}</h3><p>${p.subtitle}</p><div class="product-actions"><button class="details-button" data-detail="${p.id}">View details</button><button class="add-button" data-add="${p.id}" aria-label="Add ${p.name} to bag">+</button></div></article>`).join('')}
function renderBag(){const selected=products.filter(p=>bag[p.id]);$('#bag-items').innerHTML=selected.length?selected.map(p=>`<div class="bag-item"><img src="${p.image}" alt=""><div><h3>${p.name}</h3><div class="quantity"><button data-decrease="${p.id}" aria-label="Decrease ${p.name} quantity">−</button><span>${bag[p.id]}</span><button data-add="${p.id}" aria-label="Increase ${p.name} quantity">+</button></div></div><button class="remove" data-remove="${p.id}">Remove</button></div>`).join(''):'<p>Your bag is waiting for a little goodness. Explore the collection to save your favorites.</p>'}
function showDetails(id){const p=products.find(p=>p.id===id);$('#product-detail').innerHTML=`<img src="${p.image}" alt="${p.name} concept photograph"><p class="eyebrow">${p.tag}</p><h2>${p.name}</h2><p>${p.description}</p><p class="bag-note">Collection preview · Price and availability coming soon.</p><button class="button" data-add="${p.id}">Save to your bag <span>+</span></button>`;$('#product-dialog').showModal()}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]'),detail=e.target.closest('[data-detail]'),remove=e.target.closest('[data-remove]'),decrease=e.target.closest('[data-decrease]'),filter=e.target.closest('[data-filter]');if(add)addProduct(add.dataset.add);if(detail)showDetails(detail.dataset.detail);if(remove){delete bag[remove.dataset.remove];saveBag()}if(decrease){if(--bag[decrease.dataset.decrease]===0)delete bag[decrease.dataset.decrease];saveBag()}if(filter){document.querySelectorAll('[data-filter]').forEach(b=>{const active=b===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});renderProducts(filter.dataset.filter)}if(e.target.closest('.close'))e.target.closest('dialog').close()});
$('#open-bag').addEventListener('click',()=>$('#bag-dialog').showModal());$('#continue-shopping').addEventListener('click',()=>{$('#bag-dialog').close();$('#shop').scrollIntoView()});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#year').textContent=new Date().getFullYear();renderProducts();saveBag();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_product_to_preview_bag',description:'Save a product to the local preview bag. Does not place an order or charge a payment.',inputSchema:{type:'object',properties:{productId:{type:'string',enum:products.map(p=>p.id)}},required:['productId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.productId!=='string'||Object.keys(input).some(k=>k!=='productId'))throw new Error('Provide only a valid productId');return addProduct(input.productId)}})).catch(()=>{})}catch{}}

